# -*- coding: utf-8 -*-
LANG = 'ar'
STORIES = {
    'st-b1-01': {
        'title': 'القطار المتأخر',
        'paras': [
            'هبطت روزيتا بالقرب من بلدة سوق صغيرة. غادرت آنا وماركو السفينة لزيارة محطة القطار. كانا يريدان شراء تذكرتين إلى المدينة.',
            "في المحطة، كان كثير من الناس ينتظرون على الرصيف. قالت لهما امرأة إن القطار متأخر. قالت: «هناك مشكلة في السكة».",
            'نظرت آنا إلى الساعة. كانت الساعة العاشرة بالفعل، وكان من المفترض أن يغادر قطارهما في التاسعة والنصف. جلس ماركو على مقعد وتنهّد.',
            "فتح رجل بجانبهما حقيبته وأخرج بعض الخبز. قدّم قطعة لآنا وماركو. قال بابتسامة: «يمكنكما الانتظار هنا معي».",
            'تحدثا مع الرجل عن عائلته وعمله. كان يعمل في السوق ويبيع الخضروات كل يوم. أخبرته آنا عن روزيتا ورحلتهما.',
            'أخيرًا، بعد ساعة واحدة، وصل القطار. وقف الجميع بسرعة وسار نحو الأبواب. شكرت آنا وماركو الرجل على الخبز.',
            'في القطار، نظرت آنا من النافذة إلى الحقول. كانت سعيدة لأنهما التقيا بغريب لطيف. قال ماركو إن القطار المتأخر يجلب أحيانًا مفاجأة جميلة.',
        ],
    },
    'st-b1-02': {
        'title': 'العشاء مع عائلة يوكي',
        'paras': [
            'زار طاقم روزيتا قرية هادئة لبضعة أيام. دعت يوكي سام لتناول العشاء مع عائلتها. كان سام متوترًا لأنه لم يكن يعرفهم جيدًا.',
            "فتحت والدة يوكي الباب وابتسمت بحرارة. قالت: «أهلًا وسهلًا، نحن سعداء بمجيئك». كانت رائحة الحساء والخبز الطازج تملأ البيت.",
            'على الطاولة، سأل والد يوكي سام أسئلة كثيرة عن روزيتا. شرح سام أن السفينة تزور بلدات كثيرة وتساعد الناس. استمع أخو يوكي الصغير بعينين واسعتين.',
            'أكلوا معًا الحساء والأرز والخضروات. جرّب سام طبقًا جديدًا لم يأكله من قبل. أعجبه كثيرًا وطلب المزيد.',
            'بعد العشاء، أحضرت والدة يوكي كعكة للحلوى. قالت إنها وصفة خاصة توارثتها عن والدتها. أخذ الجميع قطعة كبيرة وتحدثوا عن ذكريات قديمة.',
            'شكر سام العائلة على الأمسية الرائعة. قال إنه شعر وكأنه جزء من العائلة بالفعل. صافحه والد يوكي ودعاه للعودة قريبًا.',
            'وهما يسيران عائدين إلى السفينة، أخبر سام يوكي أنه أحب الوجبة كثيرًا. قال إن العائلات متشابهة في كل مكان: دافئة وكريمة. ابتسمت يوكي ووافقته الرأي.',
        ],
    },
    'st-b2-01': {
        'title': 'المقابلة',
        'paras': [
            'لو لم تكن روزيتا بحاجة إلى إصلاحات، لما بقي ماركو مدة كافية للتقدم بطلب عمل في بلدة الميناء. كان قد رأى إعلانًا عن وظيفة ميكانيكي وقرر أن يجرب حظه. كان فضوليًا ليرى كيف يحل الناس على الأرض مشكلاتهم من دون أدوات السفينة المتطورة.',
            'سألته القائمة على المقابلة، امرأة طويلة تدعى آنا، عن سبب رغبته في الوظيفة. شرح ماركو أنه أمضى سنوات في إصلاح الآلات في ظروف صعبة، وغالبًا بقطع غيار محدودة. أضاف أنه يفضّل أن يتعلم نظامًا جديدًا بشكل صحيح على أن يتظاهر بأنه يعرف كل شيء بالفعل.',
            "بدت آنا معجبة، لكنها أشارت إلى أن معدات الورشة أقدم بكثير مما اعتاد عليه. قالت: «لو عملت هنا، فسيتعين عليك التخلي عن بعض العادات». اعترف ماركو بأن التكيّف قد يتطلب صبرًا، لكنه كان مستعدًا للمحاولة.",
            'ثم سألته عمّا سيفعله لو تعطلت آلة في منتصف العمل من دون توفر قطع بديلة. فكّر ماركو للحظة وقال إنه سيرتجل باستخدام أي مواد متاحة، تمامًا كما فعل على متن السفينة خلال عاصفة في العام الماضي. أومأت آنا برأسها ببطء، وهي تفكر بوضوح في إجابته.',
            'قرب نهاية المقابلة، سألته آنا عمّا إذا كان بإمكانه الالتزام بالبقاء حتى بعد رحيل روزيتا في النهاية. تردد ماركو، معترفًا بأنه لم يكن متأكدًا من المدة التي سيبقاها في البلدة. كان يعتقد أن الصدق أهم من أن يقول لها ما تريد سماعه.',
            'شكرته آنا على صراحته وقالت إنها ستناقش الأمر مع شركائها قبل اتخاذ القرار. ذكرت أن معظم المتقدمين يبالغون في وصف خبرتهم، وأن صراحته كانت لافتة. غادر ماركو الورشة غير متأكد مما إذا كان قد عزز فرصه أم أضرّ بها.',
            'بعد أيام قليلة، وصلت رسالة تدعوه للعودة لأسبوع تجريبي. أدرك ماركو أن صدقه، وليس مهارته التقنية وحدها، هو ما أقنعهم بمنحه فرصة. تساءل عمّا إذا كان سيضطر في النهاية إلى الاختيار بين الورشة والنجوم.',
        ],
    },
    'st-b2-02': {
        'title': 'غرفة الانتظار',
        'paras': [
            'عندما لم تختفِ حمى سام، اقترح طبيب السفينة أن يزور المستشفى المحلي، إذ إن معدات البلدة يمكنها إجراء فحوصات تفتقر إليها روزيتا. رافقته يوكي، جزئيًا بدافع القلق وجزئيًا بدافع الفضول لمعرفة كيفية عمل المستشفى. لم يتوقع أي منهما أن تكون غرفة الانتظار مزدحمة إلى هذا الحد.',
            'جلسا بين رجل مسنّ يقرأ جريدة وأم شابة تحاول تهدئة طفلها الباكي. لو كانت يوكي تعرف أن الانتظار سيطول هكذا، لأحضرت شيئًا تقرأه. لكنها بدلًا من ذلك راقبت الساعة واستمعت إلى الأحاديث الخافتة من حولها.',
            'بعد ما يقارب ساعتين، نادت ممرضة اسم سام وقادته نحو غرفة الفحص. عرضت يوكي مرافقته، لكن الممرضة أوضحت أنه لا يُسمح عادة إلا لشخص واحد بالدخول. ضغط سام على يدها بسرعة قبل أن يختفي خلف الباب.',
            'وحدها في غرفة الانتظار، بدأت يوكي حديثًا مع الرجل المسنّ الجالس بجانبها. قال إنه يأتي إلى المستشفى كل شهر لفحص روتيني، وإن الطاقم يعامله دائمًا بلطف رغم انشغاله. وجدت يوكي صبره لافتًا، نظرًا لطول المدة التي يضطر فيها الجميع للانتظار.',
            'عندما عاد سام أخيرًا، شرح أن الطبيب لم يجد شيئًا خطيرًا، مجرد التهاب ستزيله المضادات الحيوية خلال أسبوع. شعرت يوكي بموجة ارتياح لم تدرك أنها كانت تكبتها. مازحته برفق لأنه أقلقها إلى هذا الحد.',
            'وهما يخرجان، اعترف سام بأنه كان أكثر خوفًا مما أظهر، إذ نادرًا ما يمرض على متن السفينة. قالت يوكي إن ذلك بالضبط هو سبب إصرارها على المجيء، حتى لا يواجه الأمر وحده. شكرها، وقد شعر بشيء من الحرج لمدى أهمية وجودها بالنسبة له.',
            'في طريق عودتهما إلى روزيتا، مرّا بالرجل المسنّ مرة أخرى، وهو يسير الآن ببطء نحو موقف الحافلات. لوّحت له يوكي، فلوّح لها بابتسامة متعبة لكنها صادقة. لاحظ سام أن المستشفيات، رغم كل ما فيها من انتظار وقلق، تبدو وكأنها تُظهر لطفًا هادئًا في الناس.',
        ],
    },
    'st-c1-01': {
        'title': 'خلاف في المقهى',
        'paras': [
            'أصبح المقهى بمثابة ملاذ مألوف لطاقم روزيتا خلال إقامتهم، إذ كانت طاولاته الخشبية المهترئة وضجيج الأحاديث الدائم يشكلان تباينًا مريحًا مع ممرات السفينة المعقّمة. استقر ماركو وآنا في زاويتهما المعتادة عندما استرعى انتباههما نقاش دائر على الطاولة المجاورة. كان اثنان من رواد المقهى المعتادين يتجادلان بحماس واضح حول ما إذا كانت لوائح السوق الجديدة في البلدة ستساعد التجار المحليين أم تدمرهم.',
            'أصرّ أحدهما، وهو بائع فاكهة بالمهنة، على أن اللوائح كانت محاولة مبطّنة بشكل واهٍ لتفضيل التجار الأكبر والأوفر تمويلًا على حساب الأكشاك الصغيرة مثل كشكه. ورد خصمه، الذي يدير مكتبة متواضعة قريبة، بأنه من دون رقابة ما، أصبح السوق فوضويًا، بأسعار غير موثوقة وباعة يقوّض بعضهم بعضًا حتى حافة الانهيار. لم يبدُ أي منهما مستعدًا للتنازل قيد أنملة.',
            'مالت آنا، بفضولها المعتاد، نحو ماركو واعترفت بأنها وجدت نفسها منقسمة بين الموقفين. أشار ماركو إلى أن كلا الرجلين لديه شكوى مشروعة، حتى لو تباعدت الحلول التي يقترحانها بشدة. خطر له أن مثل هذه الخلافات نادرًا ما يكون فيها شرير؛ بل غالبًا ما تضع مخاوف معقولة في مواجهة بعضها بعضًا.',
            'وقد شجّعه فنجان قهوة ثانٍ، رفع بائع الفاكهة صوته متهمًا المجلس بالرضوخ لضغط التجار الأكثر ثراءً. ردّ صاحب المكتبة، وقد بدت عليه الضيق بوضوح، بأن هذه الاتهامات لا أساس لها، وأنه هو أيضًا معرّض لخسارة زبائنه في ظل قواعد أكثر صرامة. احتدم النقاش بينهما إلى درجة أن بقية الزبائن بدأوا يلتفتون نحوهما.',
            'شعورًا منه بأن التوتر على وشك الانفجار، تدخل صاحب المقهى، فوضع طبق حلويات بين الرجلين مع ملاحظة ساخرة مفادها أن الجدال يسير بشكل أفضل على معدة ممتلئة. كسرت هذه اللفتة العداء المتصاعد، وقبل الرجلان، بشيء من الإحراج، عرض السلام. همست آنا لماركو بأنها معجبة بمهارة صاحب المقهى في نزع فتيل الموقف.',
            'بعد أن هدأ الاحتكاك المباشر، تحول الحديث نحو أرضية مشتركة: اتفق الرجلان على أن المجلس فشل في استشارة التجار العاديين قبل صياغة اللوائح. وجد ماركو أن هذا التحول دال، إذ يوحي بأن الخلاف الحقيقي لم يكن يتعلق بالسياسة نفسها بقدر ما كان يتعلق بمن يملك صوتًا في صياغتها. أومأت آنا برأسها، ملاحظة أن الإقصاء، أكثر من الخلاف نفسه، يميل إلى تغذية الاستياء.',
            'وبينما افترق الرجلان أخيرًا على علاقة ودية، تأمل ماركو في أن طاقم روزيتا كثيرًا ما يصل متوقعًا قصصًا بسيطة من الانسجام أو الصراع، ليجد بدلًا من ذلك الحقيقة الأكثر تعقيدًا: أن معظم الخلافات متجذرة في الخوف من التجاهل. وافقته آنا، مضيفة أن أكثر ما يمكن أن ينقلاه للسفينة ربما لم يكن حكمًا على من كان محقًا، بل رواية عن مدى سرعة تلاشي المرارة حالما يشعر الناس بأنهم مسموعون. غادرا المقهى وهما يتطلعان بالفعل إلى زيارتهما القادمة.',
        ],
    },
    'st-c2-01': {
        'title': 'بين الرحيلَين',
        'paras': [
            'مع اقتراب إصلاحات روزيتا من الاكتمال، كان سام قد أصبح شبه متعلق بمدير المحطة، رجل قليل الكلام يدعى ماركو، أدرك سام أن خشونته كانت تخفي تفانيًا دقيقًا للالتزام بالمواعيد يكاد يبلغ حد الطقوسية. استقرت محادثاتهما، التي كانت متكلفة في البداية، على إيقاع مريح، وامتزج كل تبادل بينهما بذلك النوع من الفكاهة الجافة التي لا يتيحها إلا الاحترام المتبادل. وكانت هذه الألفة، أكثر من أي عطل ميكانيكي متبقٍ، ما جعل سام يخترع الأعذار للتسكع قرب الرصيف.',
            'في ما كان من المفترض أن يكون صباحه الأخير في البلدة، وجد سام ماركو هادئًا على نحو غير معتاد، يلمع بمنهجية لوحة نحاسية تخلّد تأسيس المحطة قبل عقود. وعندما علّق سام على هذه العاطفية غير المألوفة، اعترف ماركو، بتردد واضح، بأنه يجد الوداع أمرًا كريهًا مهما تكرر اضطراره لتحمله بحكم مهنته. واعترف بأن هذا كان الجانب الوحيد من العمل الذي لم يتمكن يومًا من التصالح معه.',
            'وجد سام، الذي كان قد افترض أن معرفتهما أقصر من أن تستدعي هذا الصدق، نفسه متأثرًا على نحو غريب بهذا الاعتراف. اقترح أن الانزعاج ربما لم ينبع من الفراق نفسه بل من عدم التماثل الكامن فيه: فالمسافر يمضي قدمًا نحو الجدة، بينما يعود من تُرك وراءه إلى الروتين، مهما كان وقورًا. سلّم ماركو بأن للفكرة وجاهتها، وإن كان قد استاء قليلًا من وصفه بأنه مجرد من تُرك وراءه.',
            'قاطع حديثهما مكبر صوت المحطة، وهو يبث إعلانًا مشوشًا بأن الخدمة المتجهة شمالًا ستتأخر أكثر من أربعين دقيقة بسبب عطل في نظام الإشارات. تمتم ماركو، وقد بدت عليه الراحة الواضحة من هذه المهلة، بأن القدر تآمر فيما يبدو لإطالة المحادثة قليلًا. ضحك سام واقترح أن يستفيدا قدر الإمكان من هذه الوقفة غير المتوقعة.',
            'انسحبا إلى مكتب المحطة الصغير، حيث أخرج ماركو إبريق شاي كان يحتفظ به، كما اعترف بشيء من الحرج، لمثل هذه المناسبات بالضبط. خلال نصف الساعة التالية، تجوّل حديثهما من تفاصيل رحيل روزيتا اللوجستية العادية إلى أرض أكثر عمقًا: هل يمكن لحياة أُمضيت في رعاية نقطة واحدة ثابتة أن تضاهي يومًا حياة أُمضيت في حركة دائمة، أو هل كان كل منهما يستبدل شكلًا من أشكال القلق بآخر فحسب. لم يدّعِ أي منهما أنه حسم السؤال بشكل قاطع.',
            'عندما دخل القطار المتأخر أخيرًا إلى المحطة وهو يصدر أزيزًا، رافق ماركو سام إلى الرصيف بنوع من الرسمية بدا، على نحو متناقض، أنه يُلين اللحظة بدلًا من أن يُصلّبها. مدّ يده، ثم، وكأنه يخالف حكمه الأفضل، قدّم عناقًا محرجًا بدلًا من ذلك، متمتمًا بشيء عن أنه يصنع استثناءً. طمأنه سام بأن الاستثناء متبادل ومرحّب به تمامًا.',
            'بينما أقلعت روزيتا في وقت لاحق من ذلك المساء، وجد سام نفسه يلتفت نحو المحطة مدة أطول مما تستدعيه المناسبة، وهو يقلّب في ذهنه ملاحظة ماركو السابقة عن عدم التماثل. شكّ في أن الرجل العجوز كان، بطريقته الحذرة الخاصة، يعبّر عن شيء لم يستطع سام نفسه أن يصوغه بالكلمات من قبل: أن كل رحيل يطلب من شخص أن يحمل الذكرى إلى الأمام ويترك الآخر ليحرس المكان الذي حدثت فيه. اعتقد أن هذا تقسيم عمل عادل بما فيه الكفاية، طالما لم ينسَ أي طرف دور الآخر فيه.',
        ],
    },
}
